(11, 1, '2025-05-04 13:41:12', '2025-05-04 13:41:12', '<!-- wp:group {\"className\":\"wow fadeInDown\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"80%\"}} -->  \r\n\r\n<!-- wp:group {\"className\":\"wow fadeInDown\",\"layout\":{\"type\":\"constrained\",\"contentSize\":\"80%\"}} -->\r\n<div class=\"wp-block-group wow fadeInDown\"><!-- wp:columns {\"className\":\"header-box\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|40\",\"right\":\"0\",\"bottom\":\"var:preset|spacing|40\",\"left\":\"0\"}}}} -->\r\n<div class=\"wp-block-columns header-box\" style=\"padding-top:var(--wp--preset--spacing--40);padding-right:0;padding-bottom:var(--wp--preset--spacing--40);padding-left:0\"><!-- wp:column {\"verticalAlignment\":\"bottom\",\"width\":\"25%\"} -->\r\n<div class=\"wp-block-column is-vertically-aligned-bottom\" style=\"flex-basis:25%\"><!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"justifyContent\":\"center\"}} -->\r\n<div class=\"wp-block-group\"><!-- wp:site-logo {\"width\":151,\"align\":\"center\",\"className\":\"is-style-default\"} /-->\r\n<!-- wp:html -->\r\n<div style=\";text-align:left;line-height:1;\">\r\n     <a href=\"https://tinfoxconsulting.com/\"\r\n       class=\"tinfox-logo-title\" style=\"text-decoration:none;\">\r\n    <div style=\"font-size:35px;font-weight:600;\">Tinfox</div>\r\n    <div style=\"font-size:17px;font-weight:400;margin-top:4px;margin-left:25px;\">Consulting</div>\r\n</a>\r\n</div>\r\n<!-- /wp:html --></div>\r\n\r\n<!-- /wp:group -->\r\n</div>\r\n<!-- /wp:column -->\r\n<!-- wp:column {\"verticalAlignment\":\"center\",\"width\":\"50%\"} -->\r\n<div class=\"wp-block-column is-vertically-aligned-center\" style=\"flex-basis:50%\"><!-- wp:navigation {\"ref\":9,\"className\":\"is-head-menu\",\"style\":{\"typography\":{\"textTransform\":\"uppercase\"}},\"fontFamily\":\"bricolage-grotesque\",\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} /--></div>\r\n<!-- /wp:column -->\r\n\r\n<!-